static void testChokeGroups(const File& root,Assets& assets){
    auto file=root.getChildFile("choke-stereo.wav");{AudioBuffer<float> audio(2,96000);for(int n=0;n<96000;++n){audio.setSample(0,n,.35f*(float)std::sin(n*2*MathConstants<double>::pi*220/48000));audio.setSample(1,n,.2f*(float)std::cos(n*2*MathConstants<double>::pi*330/48000));}auto stream=file.createOutputStream();WavAudioFormat format;std::unique_ptr<AudioFormatWriter> writer(stream?format.createWriterFor(stream.get(),48000,2,24,{},0):nullptr);expect(writer!=nullptr,"create stereo choke fixture");if(!writer)return;stream.release();expect(writer->writeFromAudioSampleBuffer(audio,0,96000),"write stereo choke fixture");}
    auto song=emptyProject();song.songMode=true;song.loop=false;song.bpm=120;song.delayReturn=0;song.masterSoftClip=false;song.tracks[7].instrument=Instrument::sample;song.tracks[7].samplePath=file.getFullPathName();song.tracks[7].attack=.001f;song.tracks[7].release=2;song.tracks[7].sampleLoop=true;song.tracks[7].send=0;song.tracks[6].instrument=Instrument::hat;song.tracks[6].volume=0;song.tracks[6].send=0;song.patterns[0].length=4;song.patterns[0].lanes[7]={{0,4,60,.8f}};song.patterns[0].lanes[6]={{1,.1,42,.8f}};Clip a;a.track=7;a.length=4;Clip b=a;b.track=6;song.clips={a,b};
    auto dry=render(song,assets,root,96000,127);auto grouped=song;grouped.tracks[7].chokeGroup=grouped.tracks[6].chokeGroup=1;auto audio=render(grouped,assets,root,96000,256);
    double beforeAudio=0,after=0,reference=0;for(int c=0;c<2;++c)for(int n=0;n<96000;++n){if(n<24000)beforeAudio=jmax(beforeAudio,(double)std::abs(audio.getSample(c,n)-dry.getSample(c,n)));if(n>=24400){after+=std::abs(audio.getSample(c,n));reference+=std::abs(dry.getSample(c,n));}}
    expect(beforeAudio==0&&reference>1&&after<1e-5,"accepted closing hit silences both sampler channels after the bounded fade, preserving earlier audio");
    auto another=render(grouped,assets,root,96000,31);double error=0;for(int c=0;c<2;++c)for(int n=0;n<96000;++n)error=jmax(error,(double)std::abs(another.getSample(c,n)-audio.getSample(c,n)));expect(error<1e-6,"choke onset and fade are independent of callback size");
    // Fades occur at the voice before channel inserts. A room tail is retained.
    auto wet=grouped;wet.tracks[7].mixer.reverb=true;wet.tracks[7].mixer.reverbMix=.6f;wet.tracks[7].mixer.room=.8f;auto tails=render(wet,assets,root,96000,127);expect(tails.getMagnitude(0,25000,10000)>.00001f,"choke closes voices while retaining existing insert reverb tails");
    for(int choice=0;choice<5;++choice){auto untouched=grouped;if(choice==0)untouched.tracks[6].chokeGroup=2;if(choice==1)untouched.tracks[6].mute=true;if(choice==2)untouched.tracks[7].solo=true;if(choice==3)untouched.patterns[0].lanes[6][0].probability=0;if(choice==4)untouched.patterns[0].lanes[6][0].velocity=0;auto referenceSong=untouched;referenceSong.tracks[7].chokeGroup=referenceSong.tracks[6].chokeGroup=0;auto x=render(untouched,assets,root,96000,127),y=render(referenceSong,assets,root,96000,127);bool same=true;for(int c=0;c<2;++c)for(int n=0;n<96000;++n)same&=x.getSample(c,n)==y.getSample(c,n);expect(same,"unrelated, muted, Solo-excluded, skipped and zero-velocity notes cannot choke a source");}
    auto self=song;self.tracks[7].chokeGroup=1;self.patterns[0].lanes[6].clear();self.patterns[0].lanes[7]={{0,4,60,.8f},{1,.15,72,.8f}};auto selfAudio=render(self,assets,root,96000,127);auto selfReference=self;selfReference.tracks[7].chokeGroup=0;selfReference.patterns[0].lanes[7].erase(selfReference.patterns[0].lanes[7].begin());auto onlyNew=render(selfReference,assets,root,96000,127);error=0;for(int c=0;c<2;++c)for(int n=26000;n<96000;++n)error=jmax(error,(double)std::abs(selfAudio.getSample(c,n)-onlyNew.getSample(c,n)));expect(selfAudio.getMagnitude(0,24500,3000)>.00001f&&error<1e-6,"same-channel retriggers choke previous sample voices while keeping the new voice");
    // A short later hit must still suppress an older long gate at seek/resume.
    auto seek=makeEngine(grouped,assets,root);seek->seekRequested.store(2);AudioBuffer<float> silence(2,2048);seek->render(silence.getWritePointer(0),silence.getWritePointer(1),2048);expect(silence.getMagnitude(0,0,2048)==0&&silence.getMagnitude(1,0,2048)==0,"seeking after an ended closing hit never resurrects an older held sample");
    auto resume=makeEngine(grouped,assets,root);AudioBuffer<float> block(2,256);for(int n=0;n<100;++n)resume->render(block.getWritePointer(0),block.getWritePointer(1),256);resume->playing.store(false);resume->render(block.getWritePointer(0),block.getWritePointer(1),256);resume->start();resume->render(block.getWritePointer(0),block.getWritePointer(1),256);expect(block.getMagnitude(0,0,256)==0,"pause/resume retains choke history through timeline gate selection");
    // Native generator voices use the same fade, not only sampler playback.
    for(auto instrument:{Instrument::openHat,Instrument::analog,Instrument::fm,Instrument::physical}){auto native=grouped;native.tracks[7].samplePath.clear();native.tracks[7].instrument=instrument;native.tracks[7].synth.sustain=.8f;native.tracks[7].synth.decay=2;auto x=render(native,assets,root,96000,127);expect(x.getMagnitude(0,0,20000)>.00001f&&x.getMagnitude(0,26000,60000)<1e-5f,"built-in drum and synth sources honor shared choke groups");}
    auto audition=makeEngine(grouped,assets,root);audition->playing.store(false);audition->audition(7,60,true,.8f,4);audition->render(block.getWritePointer(0),block.getWritePointer(1),256);expect(block.getMagnitude(0,0,256)>.00001f,"typing/virtual audition starts a grouped source");audition->audition(6,42,true,.8f,.1f);for(int n=0;n<4;++n)audition->render(block.getWritePointer(0),block.getWritePointer(1),256);expect(block.getMagnitude(0,0,256)==0,"audition hits close other grouped voices with the same bounded fade");
    auto loop=grouped;loop.loop=true;loop.markers={{"loop","Choke loop",.25,3,0}};loop.loopSection="loop";auto looping=makeEngine(loop,assets,root);for(int n=0;n<700;++n)looping->render(block.getWritePointer(0),block.getWritePointer(1),256);expect(looping->completedLoops.load()>1&&std::isfinite(block.getMagnitude(0,0,256)),"group state remains bounded across repeated section loops");
    RenderSettings settings;settings.bits=32;settings.endBeat=4;settings.tailSeconds=0;auto wav=root.getChildFile("choke-full.wav");expect(renderAudio(grouped,assets,root,wav,settings).wasOk(),"choke groups export through the shared renderer");String issue;auto sample=assets.load(wav,issue);error=0;if(sample&&sample->audio.getNumSamples()==96000){for(int c=0;c<2;++c)for(int n=0;n<96000;++n)error=jmax(error,(double)std::abs(audio.getSample(c,n)-sample->audio.getSample(c,n)));}else error=1;expect(error<1e-6,"float export agrees with actual choke callback audio");
    auto stem=root.getChildFile("choke-stem.wav");expect(renderAudio(grouped,assets,root,stem,settings,7).wasOk(),"isolated stem retains other channels' choke event timing");sample=assets.load(stem,issue);error=0;if(sample&&sample->audio.getNumSamples()==96000){for(int c=0;c<2;++c)for(int n=0;n<96000;++n)error=jmax(error,(double)std::abs(audio.getSample(c,n)-sample->audio.getSample(c,n)));}else error=1;expect(error<1e-6,"silent closing-channel stem dependencies match the full mix without leaking their sound");
    for(int rate:{44100,96000}){auto format=settings;format.sampleRate=rate;auto path=root.getChildFile("choke-"+String(rate)+".wav");expect(renderAudio(grouped,assets,root,path,format).wasOk(),"choke export supports additional native sample rates");auto rendered=assets.load(path,issue);int first=(int)std::ceil(rate*.515);expect(rendered&&rendered->audio.getNumSamples()==2*rate&&rendered->audio.getMagnitude(0,0,rate/3)>.00001f&&rendered->audio.getMagnitude(0,first,rate-first)<1e-5f,"closing fade follows seconds rather than a fixed 48 kHz sample count");}
    settings.startBeat=1.5;settings.endBeat=3;auto range=root.getChildFile("choke-range.wav");expect(renderAudio(grouped,assets,root,range,settings).wasOk(),"range render warms up prior choke events");sample=assets.load(range,issue);expect(sample&&sample->audio.getMagnitude(0,0,sample->audio.getNumSamples())<1e-5f,"range starting after a closed hit stays silent");
    auto path=root.getChildFile("choke.pulse");Project reopened;expect(saveProject(grouped,path).wasOk()&&loadProject(path,reopened).wasOk()&&reopened.tracks[6].chokeGroup==1&&reopened.tracks[7].chokeGroup==1,"schema 33 saves shared source groups");auto original=projectToJson(grouped);original.getDynamicObject()->setProperty("schema",32);auto before=JSON::toString(projectToJson(reopened));expect(projectFromJson(original,reopened).failed()&&JSON::toString(projectToJson(reopened))==before,"nonzero groups mislabeled as schema 32 reject without replacing a project");original=projectToJson(song);original.getDynamicObject()->setProperty("schema",32);for(auto& track:*original["tracks"].getArray())track.getDynamicObject()->removeProperty("chokeGroup");expect(projectFromJson(original,reopened).wasOk()&&reopened.tracks[7].chokeGroup==0,"schema-32 sources migrate with groups off");
    for(var bad:{var(true),var("1"),var(-1),var(17),var(1.5)}){auto malformed=projectToJson(grouped);malformed["tracks"][7].getDynamicObject()->setProperty("chokeGroup",bad);expect(projectFromJson(malformed,reopened).failed(),"group identities reject booleans, strings, out-of-range and fractional numbers");}
    auto malformed=projectToJson(grouped);malformed["tracks"][7].getDynamicObject()->removeProperty("chokeGroup");expect(projectFromJson(malformed,reopened).failed(),"schema 33 requires explicit source membership");auto bus=grouped;bus.tracks[6].isBus=true;Project checked;expect(projectFromJson(projectToJson(bus),checked).failed(),"buses cannot have source choke membership");
    Project edited;auto ops=JSON::parse(R"([{"op":"set_track","track":7,"chokeGroup":16},{"op":"set_track","track":6,"chokeGroup":16}])");expect(applyControlEdits(song,ops,edited).wasOk()&&edited.tracks[6].chokeGroup==16&&edited.tracks[7].chokeGroup==16,"MCP sets shared group membership atomically");before=JSON::toString(projectToJson(edited));ops[1].getDynamicObject()->setProperty("chokeGroup",17);expect(applyControlEdits(song,ops,edited).failed()&&JSON::toString(projectToJson(edited))==before,"invalid membership rolls back a full MCP batch");
    BouncePlan bounce;expect(planTrackBounce(grouped,7,0,assets.availableBytes(),bounce).failed(),"shared-group source bounce rejects rather than removing timing dependencies from other channels");auto own=grouped;own.tracks[6].chokeGroup=0;expect(planTrackBounce(own,7,0,assets.availableBytes(),bounce).wasOk(),"a self-contained group still supports source bounce");
}
